describe('Google OAuth Login', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should successfully log in with Google OAuth and redirect to dashboard', () => {
    // Intercept the Google OAuth redirect endpoint
    cy.intercept('GET', '/api/auth/google/callback').as('googleCallback');

    // Click the Google login button
    cy.get('[data-testid="google-login-button"]').click();

    // Wait for the OAuth callback
    cy.wait('@googleCallback');

    // Verify successful login and redirect
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome');
    cy.get('[data-testid="user-profile-icon"]').should('be.visible');
  });

  it('should handle Google OAuth failure and display error message', () => {
    // Intercept the Google OAuth redirect endpoint and simulate an error response
    cy.intercept('GET', '/api/auth/google/callback', {
      statusCode: 401,
      body: { error: 'Invalid credentials' }
    }).as('googleCallbackError');

    // Click the Google login button
    cy.get('[data-testid="google-login-button"]').click();

    // Wait for the failed OAuth callback
    cy.wait('@googleCallbackError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Login failed');
    cy.get('[data-testid="error-message"]').should('contain', 'Please try again');

    // Verify user is still on the login page
    cy.url().should('include', '/login');
    cy.get('[data-testid="google-login-button"]').should('be.visible');
  });
});
